function openDB(){ return new Promise((resolve,reject)=>{ const req=indexedDB.open(DB_NAME,1); req.onupgradeneeded=()=>req.result.createObjectStore(STORE,{keyPath:'id'}); req.onsuccess=()=>resolve(req.result); req.onerror=()=>reject(req.error); }); }
async function getAssets(){ const db=await openDB(); return new Promise((res,rej)=>{const r=db.transaction(STORE).objectStore(STORE).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)}); }
async function saveAsset(asset){ const db=await openDB(); return new Promise((res,rej)=>{const r=db.transaction(STORE,'readwrite').objectStore(STORE).put(asset);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)}); }
async function removeAsset(id){ const db=await openDB(); return new Promise((res,rej)=>{const r=db.transaction(STORE,'readwrite').objectStore(STORE).delete(id);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)}); }
