  const beginMarquee=event=>{if(event.button!==0||event.target.closest('article,button,input,select,textarea'))return;event.currentTarget.setPointerCapture(event.pointerId);marqueeStart.current={x:event.clientX,y:event.clientY,moved:false};marqueeBase.current=new Set(event.ctrlKey||event.metaKey?selectedIds:[]);setMarquee({left:event.clientX,top:event.clientY,width:0,height:0})};
  const moveMarquee=event=>{const start=marqueeStart.current;if(!start)return;const dx=event.clientX-start.x,dy=event.clientY-start.y;if(Math.abs(dx)>3||Math.abs(dy)>3)start.moved=true;const box={left:Math.min(start.x,event.clientX),top:Math.min(start.y,event.clientY),right:Math.max(start.x,event.clientX),bottom:Math.max(start.y,event.clientY)};setMarquee({left:box.left,top:box.top,width:box.right-box.left,height:box.bottom-box.top});if(!start.moved)return;const ids=new Set(marqueeBase.current);document.querySelectorAll('article[data-asset-id]').forEach(element=>{const rect=element.getBoundingClientRect();if(rect.right>=box.left&&rect.left<=box.right&&rect.bottom>=box.top&&rect.top<=box.bottom)ids.add(element.dataset.assetId)});setSelectedIds([...ids]);setSelected(null)};
  const endMarquee=event=>{const start=marqueeStart.current;if(!start)return;if(!start.moved){setSelectedIds([]);setSelected(null)}if(event.currentTarget.hasPointerCapture(event.pointerId))event.currentTarget.releasePointerCapture(event.pointerId);marqueeStart.current=null;setMarquee(null)};
  const beginSidebarResize=event=>{if(event.button!==0)return;event.preventDefault();sidebarResizing.current=true;event.currentTarget.setPointerCapture(event.pointerId);document.body.classList.add('resizing-sidebar')};
  const moveSidebarResize=event=>{if(sidebarResizing.current)setSidebarWidth(clampSidebarWidth(event.clientX))};
  const endSidebarResize=event=>{if(!sidebarResizing.current)return;sidebarResizing.current=false;if(event.currentTarget.hasPointerCapture(event.pointerId))event.currentTarget.releasePointerCapture(event.pointerId);document.body.classList.remove('resizing-sidebar');const width=clampSidebarWidth(event.clientX);setSidebarWidth(width);localStorage.setItem(SIDEBAR_WIDTH_KEY,String(width))};
