  const importFiles=async files=>{ for(const file of [...files].filter(f=>/^(image|video|audio)\//.test(f.type))){ const tempUrl=URL.createObjectURL(file);const dims=file.type.startsWith('image/')?await new Promise(res=>{const im=new Image();im.onload=()=>res([im.naturalWidth,im.naturalHeight]);im.onerror=()=>res([0,0]);im.src=tempUrl}):[0,0];const a={id:crypto.randomUUID(),name:file.name.replace(/\.[^.]+$/,''),type:file.type,size:file.size,width:dims[0],height:dims[1],tags:[],favorite:false,createdAt:Date.now(),blob:file,url:tempUrl};await saveAsset({...a,url:''});assetsRef.current=[a,...assetsRef.current];setAssets(assetsRef.current); }};
  const patch=(id,data)=>{const target=assetsRef.current.find(a=>a.id===id);if(!target)return;const updated={...target,...data};assetsRef.current=assetsRef.current.map(a=>a.id===id?updated:a);setAssets(assetsRef.current);setSelected(s=>s?.id===id?updated:s);if(desktop){desktopChanges.current.set(id,{...(desktopChanges.current.get(id)||{}),...data});clearTimeout(desktopTimers.current.get(id));desktopTimers.current.set(id,setTimeout(async()=>{const changes=desktopChanges.current.get(id);desktopChanges.current.delete(id);desktopTimers.current.delete(id);if(!changes)return;try{const result=await window.nestDesktop.updateAsset(id,changes);if(result?.error){setMessage(result.error);setTimeout(()=>setMessage(''),5000);const current=await window.nestDesktop.currentLibrary();applyLibrary(current);return}applyLibrary(result)}catch(error){setMessage(`保存失败：${error.message}`);setTimeout(()=>setMessage(''),5000)}},300));return}writePending(id,data);pendingSaves.current.set(id,updated);clearTimeout(saveTimers.current.get(id));saveTimers.current.set(id,setTimeout(()=>{const pending=pendingSaves.current.get(id);if(pending)saveAsset({...pending,url:''}).then(()=>clearPending(id));pendingSaves.current.delete(id);saveTimers.current.delete(id)},250))};
  const del=async id=>{if(desktop){clearTimeout(desktopTimers.current.get(id));desktopTimers.current.delete(id);desktopChanges.current.delete(id);applyLibrary(await window.nestDesktop.deleteAsset(id));return}clearTimeout(saveTimers.current.get(id));await removeAsset(id);assetsRef.current=assetsRef.current.filter(a=>a.id!==id);setAssets(assetsRef.current);setSelected(null)};
  useEffect(()=>{const onShortcut=event=>{if(event.target.closest('input,textarea,select'))return;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='a'){event.preventDefault();toggleSelectAll()}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='c'){const asset=selected||assetsRef.current.find(item=>selectedIds.includes(item.id));if(asset){event.preventDefault();copyAssetToClipboard(asset)}}if(previewId&&event.key==='ArrowLeft')movePreview(-1);if(previewId&&event.key==='ArrowRight')movePreview(1);if(previewId&&event.key.toLowerCase()==='r')setRotation(value=>(value+90)%360);if(previewId&&event.key==='0')resetPreviewView()};window.addEventListener('keydown',onShortcut);return()=>window.removeEventListener('keydown',onShortcut)},[shown,selectedIds,selected,previewId]);
