      {shown.length?<section className="masonry" onPointerDown={beginMarquee} onPointerMove={moveMarquee} onPointerUp={endMarquee} onPointerCancel={endMarquee}>{displayed.map(a=><article key={a.id} data-asset-id={a.id} draggable={desktop} onDragStart={e=>startAssetDrag(e,a)} onDragEnd={()=>{externalDragActive.current=false;clearTimeout(externalDragTimer.current);setDropFolderId(undefined);setDrag(false)}} className={`${selected?.id===a.id?'selected':''} ${selectedIds.includes(a.id)?'multi-selected':''}`} onContextMenu={e=>{e.preventDefault();e.stopPropagation();setSelected(a);setContextMenu({x:e.clientX,y:e.clientY,asset:a})}} onDoubleClick={()=>{setPreviewId(a.id);resetPreviewView()}} onClick={e=>clickAsset(e,a)}><div className="thumb" draggable={desktop} onDragStart={e=>startAssetDrag(e,a)} title="拖到桌面、其他软件或浏览器上传区域"><Media asset={a} onSize={(width,height)=>{if(!a.width)patch(a.id,{width,height})}}/><button className="select-dot" aria-label="选择素材" onClick={e=>{e.stopPropagation();lastSelectedId.current=a.id;toggleSelected(a.id)}}>{selectedIds.includes(a.id)?'✓':''}</button><button aria-label={a.favorite?'取消收藏':'收藏'} title={a.favorite?'取消收藏':'收藏'} className={a.favorite?'fav yes':'fav'} onClick={e=>{e.stopPropagation();patch(a.id,{favorite:!a.favorite})}}><Heart size={17} fill={a.favorite?'currentColor':'none'}/></button><div className="dimensions">{a.width||'—'} × {a.height||'—'}</div></div><div className="meta" title="拖动名称可移动到内部文件夹"><strong>{a.name}</strong><div>{a.tags.slice(0,2).map(t=><span key={t}>{t}</span>)}</div></div></article>)}</section>:!contentFolders.length&&<div className="empty"><ImageIcon size={34}/><h2>这里还没有素材或文件夹</h2><p>新建文件夹，或拖入图片、视频和外部文件夹。</p><button onClick={desktop?nativeImport:()=>input.current.click()}>选择图片</button></div>}
