    {previewAsset&&<Preview asset={previewAsset} zoom={zoom} rotation={rotation} checker={checker} setZoom={setZoom} setRotation={setRotation} setChecker={setChecker} reset={resetPreviewView} close={()=>setPreviewId(null)} previous={()=>movePreview(-1)} next={()=>movePreview(1)}/>}
    {desktop&&ready&&!library&&<div className="welcome"><div className="welcome-card"><div className="mark big">N</div><h1>建立你的素材资源库</h1><p>资源库会在你选择的文件夹中保存原始素材和索引，可整体备份或迁移。</p>{message&&<span className="welcome-error">{message}</span>}<button className="primary" onClick={createLibrary}>创建资源库</button><button onClick={openLibrary}>打开已有资源库</button></div></div>}
